	t3 := fr.LazyMul(&s, &s)

	fr.LazyAdd(&s, &x.A0, &x.A1)
	t4 := fr.LazyMul(&s, &s)

	fr.LazyAdd(&s, &x.A0, &x.A2)
	t5 := fr.LazyMul(&s, &s)

	z.A0[0] = reduceSparse(t0 + t3 + 3*q - t1 - t2)
	z.A1[0] = reduceSparse(t4 + t3 + 4*q - t0 - t1 - t1)
